def run_sql(sql, description=""):
    print(f"Running SQL: {description or sql[:80]}")
    resp = w.statement_execution.execute_statement(
        statement=sql,
        warehouse_id=warehouse_id,
        wait_timeout="60s",
    )
    if resp.status.state.value not in ["SUCCEEDED"]:
        # Wait for it
        stmt_id = resp.statement_id
        for _ in range(30):
            time.sleep(2)
            resp = w.statement_execution.get_statement(stmt_id)
            state = resp.status.state.value
            if state == "SUCCEEDED":
                break
            elif state in ["FAILED", "CANCELED", "CLOSED"]:
                raise Exception(f"SQL failed: {resp.status.error}")
    return resp
